exercises.solution:
function conferirMatricula(aluno) {
  if (!aluno.atestado) {
    return 'Falta o atestado médico';
  }
  if (aluno.idade < 16) {
    return 'Só a partir de 16 anos';
  }
  if (!aluno.pagou) {
    return 'Falta pagar a matrícula';
  }
  return 'Matrícula feita';
}

console.log(conferirMatricula({ atestado: false, idade: 15, pagou: false }));
console.log(conferirMatricula({ atestado: true, idade: 15, pagou: true }));
console.log(conferirMatricula({ atestado: true, idade: 22, pagou: false }));
console.log(conferirMatricula({ atestado: true, idade: 22, pagou: true }));

