exercises.solution:
function lerLitros(texto) {
  const litros = Number(texto.trim().replace(',', '.'));
  if (Number.isNaN(litros)) {
    return null;
  }
  if (litros <= 0) {
    return null;
  }
  if (litros > 60) {
    return null;
  }
  return litros;
}

console.log(lerLitros('12,5'));
console.log(lerLitros(' 40 '));
console.log(lerLitros('cheio'));
console.log(lerLitros('0'));
console.log(lerLitros('-5'));
console.log(lerLitros('75'));

